// valueOf returns the value of p, or the zero value for nil. It fills an SDK
// field that is a value, not a pointer.
func valueOf[T any](p *T) T {
	var zero T
	if p == nil {
		return zero
	}
	return *p
}

// elements is a types.Set or a types.List.
type elements interface {
	IsNull() bool
	IsUnknown() bool
	ElementsAs(ctx context.Context, target interface{}, allowUnhandled bool) diag.Diagnostics
}

// expandElements returns the elements of v. It returns nil for a null
// value, and a non-nil slice for an empty value.
func expandElements[T any](ctx context.Context, p path.Path, v elements, diags *diag.Diagnostics) []T {
	if v.IsNull() || v.IsUnknown() {
		return nil
	}
	out := []T{}
	for _, d := range v.ElementsAs(ctx, &out, false) {
		diags.Append(diag.WithPath(p, d))
	}
	if out == nil {
		out = []T{}
	}
	return out
}

func expandStrings[T ~string](ctx context.Context, p path.Path, v elements, diags *diag.Diagnostics) []T {
	items := expandElements[string](ctx, p, v, diags)
	if items == nil {
		return nil
	}
	out := make([]T, 0, len(items))
	for _, s := range items {
		out = append(out, T(s))
	}
	return out
}

// expandStringsSet preserves null and empty, and removes duplicate wire values.
func expandStringsSet[T ~string](ctx context.Context, p path.Path, v elements, diags *diag.Diagnostics) []T {
	items := expandStrings[T](ctx, p, v, diags)
	if items == nil {
		return nil
	}
	out := make([]T, 0, len(items))
	seen := make(map[T]struct{}, len(items))
	for _, item := range items {
		if _, ok := seen[item]; ok {
			continue
		}
		seen[item] = struct{}{}
		out = append(out, item)
	}
	return out
}

// expandSet preserves null and empty, and removes duplicate scalar values.
func expandSet[T comparable](ctx context.Context, p path.Path, v elements, diags *diag.Diagnostics) []T {
	items := expandElements[T](ctx, p, v, diags)
	if items == nil {
		return nil
	}
	out := make([]T, 0, len(items))
	seen := make(map[T]struct{}, len(items))
	for _, item := range items {
		if _, ok := seen[item]; ok {
			continue
		}
		seen[item] = struct{}{}
		out = append(out, item)
	}
	return out
}

func expandString(v types.String) *string {
	if v.IsNull() || v.IsUnknown() {
		return nil
	}
	s := v.ValueString()
	return &s
}

func expandBool(v types.Bool) *bool {
	if v.IsNull() || v.IsUnknown() {
		return nil
	}
	b := v.ValueBool()
	return &b
}

func expandFloat64(v types.Float64) *float64 {
	if v.IsNull() || v.IsUnknown() {
		return nil
	}
	f := v.ValueFloat64()
	return &f
}

func expandEnum[T ~string](v types.String) *T {
	if v.IsNull() || v.IsUnknown() {
		return nil
	}
	e := T(v.ValueString())
	return &e
}

// expandUint64 returns the decimal string of v. The API sends 64-bit
// numbers as strings.
func expandUint64(p path.Path, v types.Int64, diags *diag.Diagnostics) *string {
	if v.IsNull() || v.IsUnknown() {
		return nil
	}
	n := v.ValueInt64()
	if n < 0 {
		diags.AddAttributeError(p, "Invalid value", fmt.Sprintf("The value %d is negative. The API accepts only unsigned numbers.", n))
		return nil
	}
	s := strconv.FormatInt(n, 10)
	return &s
}

// flattenUint64 parses the decimal string of an unsigned 64-bit number. A
// value larger than the Terraform Int64 maximum is an error.
func flattenUint64(p path.Path, v *string, diags *diag.Diagnostics) types.Int64 {
	if v == nil {
		return types.Int64Null()
	}
	n, err := strconv.ParseUint(*v, 10, 64)
	if err != nil {
		diags.AddAttributeError(p, "Invalid API value", fmt.Sprintf("The API returned %q, which is not an unsigned number: %s", *v, err))
		return types.Int64Null()
	}
	if n > math.MaxInt64 {
		diags.AddAttributeError(p, "Invalid API value", fmt.Sprintf("The API returned %d, which is larger than the Terraform maximum %d.", n, int64(math.MaxInt64)))
		return types.Int64Null()
	}
	return types.Int64Value(int64(n))
}

// expandEnumMapped returns the API value of a Terraform value. A value that the map lacks is an error.
func expandEnumMapped[T ~string](p path.Path, v types.String, toAPI map[string]T, diags *diag.Diagnostics) *T {
	if v.IsNull() || v.IsUnknown() {
		return nil
	}
	e, ok := toAPI[v.ValueString()]
	if !ok {
		diags.AddAttributeError(p, "Unsupported value", fmt.Sprintf("The value %q is not supported.", v.ValueString()))
		return nil
	}
	return &e
}

// flattenEnumMapped returns the Terraform value of an API value. A value that the map lacks is an error.
func flattenEnumMapped[T ~string](p path.Path, v *T, fromAPI map[T]string, diags *diag.Diagnostics) types.String {
	if v == nil {
		return types.StringNull()
	}
	s, ok := fromAPI[*v]
	if !ok {
		diags.AddAttributeError(p, "Unsupported API value", fmt.Sprintf("The API returned %q, which this resource does not support.", string(*v)))
		return types.StringNull()
	}
	return types.StringValue(s)
}

func flattenEnum[T ~string](v *T, zero string) types.String {
	if v == nil || string(*v) == zero {
		return types.StringNull()
	}
	return types.StringValue(string(*v))
}

func flattenTime(v *time.Time) types.String {
	if v == nil {
		return types.StringNull()
	}
	return types.StringValue(v.Format(time.RFC3339Nano))
}

func flattenStringsSet[T ~string](ctx context.Context, v []T, diags *diag.Diagnostics) types.Set {
	if v == nil {
		return types.SetNull(types.StringType)
	}
	return flattenSet(ctx, types.StringType, toStrings(v), diags)
}

func flattenStringsList[T ~string](ctx context.Context, v []T, diags *diag.Diagnostics) types.List {
	if v == nil {
		return types.ListNull(types.StringType)
	}
	return flattenList(ctx, types.StringType, toStrings(v), diags)
}

func invalidEnumElement(p path.Path, value, zero string, diags *diag.Diagnostics) {
	if value == zero {
		diags.AddAttributeError(p, "Invalid API enum value", fmt.Sprintf("The API returned protobuf zero enum value %q in a collection. The API must omit this element or return a concrete enum value.", value))
	}
}

func flattenEnumsSet[T ~string](ctx context.Context, p path.Path, v []T, zero string, diags *diag.Diagnostics) types.Set {
	if v == nil {
		return types.SetNull(types.StringType)
	}
	items := toStrings(v)
	sort.Strings(items)
	for _, value := range items {
		invalidEnumElement(p, value, zero, diags)
	}
	return flattenSet(ctx, types.StringType, items, diags)
}

func flattenEnumsList[T ~string](ctx context.Context, p path.Path, v []T, zero string, diags *diag.Diagnostics) types.List {
	if v == nil {
		return types.ListNull(types.StringType)
	}
	items := toStrings(v)
	for index, value := range items {
		invalidEnumElement(p.AtListIndex(index), value, zero, diags)
	}
	return flattenList(ctx, types.StringType, items, diags)
}

func toStrings[T ~string](v []T) []string {
	out := make([]string, 0, len(v))
	for _, s := range v {
		out = append(out, string(s))
	}
	return out
}

func flattenSet[T any](ctx context.Context, elem attr.Type, items []T, diags *diag.Diagnostics) types.Set {
	s, d := types.SetValueFrom(ctx, elem, items)
	diags.Append(d...)
	return s
}

func flattenList[T any](ctx context.Context, elem attr.Type, items []T, diags *diag.Diagnostics) types.List {
	l, d := types.ListValueFrom(ctx, elem, items)
	diags.Append(d...)
	return l
}

// expandMap returns the values of v. It returns nil for a null value, and a
// non-nil map for an empty value.
func expandMap[T any](ctx context.Context, p path.Path, v types.Map, diags *diag.Diagnostics) map[string]T {
	if v.IsNull() || v.IsUnknown() {
		return nil
	}
	out := map[string]T{}
	for _, d := range v.ElementsAs(ctx, &out, false) {
		diags.Append(diag.WithPath(p, d))
	}
	if out == nil {
		out = map[string]T{}
	}
	return out
}

func flattenMap[T any](ctx context.Context, elem attr.Type, items map[string]T, diags *diag.Diagnostics) types.Map {
	m, d := types.MapValueFrom(ctx, elem, items)
	diags.Append(d...)
	return m
}

func expandStringMap[T ~string](ctx context.Context, p path.Path, v types.Map, diags *diag.Diagnostics) map[string]T {
	items := expandMap[string](ctx, p, v, diags)
	if items == nil {
		return nil
	}
	out := make(map[string]T, len(items))
	for k, s := range items {
		out[k] = T(s)
	}
	return out
}

func flattenStringMap[T ~string](ctx context.Context, v map[string]T, diags *diag.Diagnostics) types.Map {
	if v == nil {
		return types.MapNull(types.StringType)
	}
	items := make(map[string]string, len(v))
	for k, s := range v {
		items[k] = string(s)
	}
	return flattenMap(ctx, types.StringType, items, diags)
}

func flattenEnumMap[T ~string](ctx context.Context, p path.Path, v map[string]T, zero string, diags *diag.Diagnostics) types.Map {
	if v == nil {
		return types.MapNull(types.StringType)
	}
	items := make(map[string]string, len(v))
	keys := make([]string, 0, len(v))
	for key, value := range v {
		items[key] = string(value)
		keys = append(keys, key)
	}
	sort.Strings(keys)
	for _, key := range keys {
		invalidEnumElement(p.AtMapKey(key), items[key], zero, diags)
	}
	return flattenMap(ctx, types.StringType, items, diags)
}
